      /* ----------------------------------------------------------------------
         OFFLINE / ERROR GRACEFUL PROCEDURAL PHOTO PLATE FALLBACK
         Ensures zero broken images even without internet connectivity.
         ---------------------------------------------------------------------- */
      function createFallbackPlate(title, code, colors = ['#B7AEA2', '#3B3630']) {
        const canvas = document.createElement('canvas');
        canvas.width = 900;
        canvas.height = 1100;
        const ctx = canvas.getContext('2d');

        const grad = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
        grad.addColorStop(0, colors[0]);
        grad.addColorStop(1, colors[1]);
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Soft architectural light beam
        const rad = ctx.createRadialGradient(260, 240, 40, 400, 460, 680);
        rad.addColorStop(0, 'rgba(255, 250, 240, 0.34)');
        rad.addColorStop(1, 'rgba(0, 0, 0, 0)');
        ctx.fillStyle = rad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Subtle geometric horizon line
        ctx.strokeStyle = 'rgba(255,255,255,0.22)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(70, canvas.height * 0.68);
        ctx.lineTo(canvas.width - 70, canvas.height * 0.68);
        ctx.stroke();

        // Archival plate markings
        ctx.fillStyle = 'rgba(255,255,255,0.75)';
        ctx.font = '300 18px monospace';
        ctx.fillText(code || 'ARCHIVE PLATE', 70, canvas.height - 95);
        ctx.font = 'italic 34px Georgia, serif';
        ctx.fillText(title || 'Untitled Study', 70, canvas.height - 54);

        return canvas.toDataURL('image/jpeg', 0.88);
      }

      function attachImageFallback(img, photo) {
        img.addEventListener('error', () => {
          if (img.dataset.fallbackApplied) return;
          img.dataset.fallbackApplied = 'true';
          img.src = createFallbackPlate(photo.title, photo.code, photo.palette);
        });
      }

