      function updateClock() {
        const el = document.getElementById('cphClock');
        if (!el) return;
        try {
          const now = new Date();
          const formatter = new Intl.DateTimeFormat('en-GB', {
            timeZone: 'Europe/Copenhagen',
            hour: '2-digit',
            minute: '2-digit',
            hour12: false
          });
          el.textContent = `CPH ${formatter.format(now)}`;
        } catch {
          el.textContent = 'CPH STUDIO';
        }
      }
      updateClock();
      setInterval(updateClock, 30000);
