      /* ----------------------------------------------------------------------
         HERO CAROUSEL
         ---------------------------------------------------------------------- */
      function initHero() {
        heroFrame.innerHTML = '';
        featuredPhotos.forEach((photo, idx) => {
          const slide = document.createElement('div');
          slide.className = 'hero-slide' + (idx === 0 ? ' active' : '');
          const img = document.createElement('img');
          img.src = photo.url;
          img.alt = photo.title;
          img.loading = idx === 0 ? 'eager' : 'lazy';
          attachImageFallback(img, photo);
          slide.appendChild(img);
          heroFrame.appendChild(slide);
        });
        updateHeroSlide(0);
        startHeroAutoplay();
      }

      function updateHeroSlide(index) {
        state.heroIndex = (index + featuredPhotos.length) % featuredPhotos.length;
        const slides = heroFrame.querySelectorAll('.hero-slide');
        slides.forEach((s, i) => s.classList.toggle('active', i === state.heroIndex));

        const p = featuredPhotos[state.heroIndex];
        heroCaptionTitle.textContent = `${p.title} — ${p.location}`;
        heroCaptionExif.textContent = `${p.camera} · ${p.lens} · ${p.exposure}`;
        heroCounter.textContent = `0${state.heroIndex + 1} / 0${featuredPhotos.length}`;
      }

      function startHeroAutoplay() {
        clearInterval(state.heroTimer);
        state.heroTimer = setInterval(() => updateHeroSlide(state.heroIndex + 1), 6200);
      }

      heroPrev.addEventListener('click', () => {
        updateHeroSlide(state.heroIndex - 1);
        startHeroAutoplay();
      });

      heroNext.addEventListener('click', () => {
        updateHeroSlide(state.heroIndex + 1);
        startHeroAutoplay();
      });

      heroFrame.addEventListener('click', () => {
        const currentPhoto = featuredPhotos[state.heroIndex];
        openLightboxById(currentPhoto.id, PHOTOS);
      });

      heroFrame.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openLightboxById(featuredPhotos[state.heroIndex].id, PHOTOS);
        }
      });

      /* ----------------------------------------------------------------------
         ARCHIVE FILTERS & GALLERY RENDERING
         ---------------------------------------------------------------------- */
      const categories = ['All', 'Architecture', 'Editorial', 'Documentary', 'Portraits'];

      function renderFilters() {
        filterGroup.innerHTML = '';
        categories.forEach(cat => {
          const count = cat === 'All' ? PHOTOS.length : PHOTOS.filter(p => p.category === cat).length;
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'filter-btn' + (state.activeCategory === cat ? ' active' : '');
          btn.setAttribute('role', 'tab');
          btn.setAttribute('aria-selected', String(state.activeCategory === cat));
          btn.innerHTML = `${cat}<span class="filter-count">${String(count).padStart(2, '0')}</span>`;
          btn.addEventListener('click', () => {
            state.activeCategory = cat;
            renderFilters();
            renderGallery();
          });
          filterGroup.appendChild(btn);
        });
      }

      function getFilteredPhotos() {
        if (state.activeCategory === 'All') return PHOTOS;
        return PHOTOS.filter(p => p.category === state.activeCategory);
      }

      function renderGallery() {
        const list = getFilteredPhotos();
        galleryGrid.setAttribute('data-view', state.viewMode);
        galleryGrid.innerHTML = '';

        // Contact Sheet Proof Header
        const sheetHeader = document.createElement('div');
        sheetHeader.className = 'contact-sheet-header mono';
        sheetHeader.innerHTML = `
          <span>PROOF SHEET · KODAK PORTRA / DIGITAL ARCHIVE · ${state.activeCategory.toUpperCase()}</span>
          <span>${String(list.length).padStart(2, '0')} FRAMES · CPH DARKROOM</span>
        `;
        galleryGrid.appendChild(sheetHeader);

        list.forEach((photo, idx) => {
          const card = document.createElement('article');
          card.className = `photo-card ${photo.layoutClass}`;
          card.setAttribute('tabindex', '0');
          card.setAttribute('role', 'button');
          card.setAttribute('aria-label', `View ${photo.title} in lightbox`);

          const frame = document.createElement('div');
          frame.className = `photo-frame ${photo.ratio}`;

          const img = document.createElement('img');
          img.src = photo.url;
          img.alt = `${photo.title} — ${photo.location}`;
          img.loading = 'lazy';
          attachImageFallback(img, photo);

          const tag = document.createElement('span');
          tag.className = 'photo-overlay-tag mono';
          tag.textContent = `${photo.camera} · ${photo.stock}`;

          frame.appendChild(img);
          frame.appendChild(tag);

          const meta = document.createElement('div');
          meta.className = 'photo-meta';
          meta.innerHTML = `
            <div>
              <h3 class="photo-title">${photo.title}</h3>
              <div class="photo-sub mono">${photo.location} &middot; ${photo.year}</div>
            </div>
            <span class="photo-index mono">${photo.code}</span>
          `;

          card.appendChild(frame);
          card.appendChild(meta);

          const openThis = () => openLightbox(list, idx);
          card.addEventListener('click', openThis);
          card.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              openThis();
            }
          });

          // Custom cursor triggers
          card.addEventListener('mouseenter', () => galleryCursor.classList.add('active'));
          card.addEventListener('mouseleave', () => galleryCursor.classList.remove('active'));

          galleryGrid.appendChild(card);
        });
      }

      viewButtons.forEach(btn => {
        btn.addEventListener('click', () => {
          state.viewMode = btn.dataset.viewMode;
          viewButtons.forEach(b => {
            const active = b.dataset.viewMode === state.viewMode;
            b.classList.toggle('active', active);
            b.setAttribute('aria-pressed', String(active));
          });
          renderGallery();
        });
      });

      /* Diptych click to open lightbox */
      document.querySelectorAll('.diptych-frame[data-open-id]').forEach(el => {
        el.addEventListener('click', () => {
          openLightboxById(Number(el.dataset.openId), PHOTOS);
