      /* Attach fallback to static portraits/monograph images as well */
      document.querySelectorAll('.diptych-frame img, .portrait-frame img').forEach((img, idx) => {
        attachImageFallback(img, {
          title: img.alt,
          code: `PLATE-0${idx + 1}`,
          palette: ['#C8BEB0', '#4A433C']
        });
      });

      /* ----------------------------------------------------------------------
         CUSTOM GALLERY CURSOR TRACKING
         ---------------------------------------------------------------------- */
      if (window.matchMedia('(pointer: fine)').matches) {
        window.addEventListener('mousemove', (e) => {
          galleryCursor.style.left = `${e.clientX}px`;
          galleryCursor.style.top = `${e.clientY}px`;
        }, { passive: true });
      }

      /* ----------------------------------------------------------------------
         LIGHTBOX VIEWER
         ---------------------------------------------------------------------- */
      function openLightboxById(id, list = PHOTOS) {
        const idx = list.findIndex(p => p.id === id);
        openLightbox(list, idx >= 0 ? idx : 0);
      }

      function openLightbox(list, index) {
        state.lightboxList = list;
        state.lightboxIndex = index;
        state.lightboxOpen = true;
        state.lightboxZoomed = false;
        updateLightboxContent();
        lightbox.classList.add('open');
        lightbox.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
        galleryCursor.classList.remove('active');
        lbCloseBtn.focus();
      }

      function closeLightbox() {
        state.lightboxOpen = false;
        state.lightboxZoomed = false;
        lbImage.classList.remove('zoomed');
        lightbox.classList.remove('open');
        lightbox.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      }

      function updateLightboxContent() {
        const list = state.lightboxList;
        state.lightboxIndex = (state.lightboxIndex + list.length) % list.length;
        const p = list[state.lightboxIndex];

        state.lightboxZoomed = false;
        lbImage.classList.remove('zoomed');
        lbZoomBtn.textContent = 'Zoom';

        lbImage.style.opacity = '0.2';
        lbImage.dataset.fallbackApplied = '';
        lbImage.src = p.url;
        lbImage.alt = p.title;
        lbImage.onload = () => { lbImage.style.opacity = '1'; };
        lbImage.onerror = () => {
          lbImage.src = createFallbackPlate(p.title, p.code, p.palette);
          lbImage.style.opacity = '1';
        };

        lbIndex.textContent = `PLATE ${String(state.lightboxIndex + 1).padStart(2, '0')} / ${String(list.length).padStart(2, '0')} · ${p.code}`;
        lbCategory.textContent = p.category;
        lbTitle.textContent = p.title;
        lbStory.textContent = p.story;
        lbLocation.textContent = p.location;
        lbYear.textContent = p.year;
        lbCamera.textContent = p.camera;
        lbLens.textContent = p.lens;
        lbExposure.textContent = p.exposure;
        lbStock.textContent = p.stock;
        lbCoords.textContent = `${p.location} · ${p.coords}`;
      }

      function toggleZoom() {
        state.lightboxZoomed = !state.lightboxZoomed;
        lbImage.classList.toggle('zoomed', state.lightboxZoomed);
        lbZoomBtn.textContent = state.lightboxZoomed ? 'Fit' : 'Zoom';
      }

      lbPrev.addEventListener('click', () => {
        state.lightboxIndex -= 1;
        updateLightboxContent();
      });

      lbNext.addEventListener('click', () => {
        state.lightboxIndex += 1;
        updateLightboxContent();
      });

      lbCloseBtn.addEventListener('click', closeLightbox);
      lbZoomBtn.addEventListener('click', toggleZoom);
      lbImage.addEventListener('click', toggleZoom);

      lbInfoBtn.addEventListener('click', () => {
        state.drawerCollapsed = !state.drawerCollapsed;
        lbDrawer.classList.toggle('collapsed', state.drawerCollapsed);
        lbInfoBtn.textContent = state.drawerCollapsed ? 'Show Notes' : 'Hide Notes';
      });

      /* Pre-fill inquiry form for a specific archival print */
      lbInquirePrint.addEventListener('click', () => {
        const p = state.lightboxList[state.lightboxIndex];
        closeLightbox();
        prefillPrintInquiry(`Print Edition Inquiry — "${p.title}" (${p.code})`);
      });

      document.getElementById('monographPrintBtn').addEventListener('click', (e) => {
        e.preventDefault();
        prefillPrintInquiry('Catalogue & Edition Inquiry — "Concrete & Salt Air" (2024 Monograph)');
      });

      function prefillPrintInquiry(noteText) {
        selectInquiryPill('Fine Art Print');
        const msgEl = document.getElementById('messageInput');
        msgEl.value = `${noteText}\n\nI would love to receive edition sizing, framing options, and availability.`;
        document.getElementById('budgetInput').value = 'Print Edition (€600–€2,500)';
        document.getElementById('inquire').scrollIntoView({ behavior: 'smooth' });
        setTimeout(() => document.getElementById('nameInput').focus(), 650);
      }

      /* Keyboard navigation inside lightbox */
      document.addEventListener('keydown', (e) => {
        if (!state.lightboxOpen) return;
        if (e.key === 'Escape') closeLightbox();
        else if (e.key === 'ArrowRight') { state.lightboxIndex += 1; updateLightboxContent(); }
        else if (e.key === 'ArrowLeft') { state.lightboxIndex -= 1; updateLightboxContent(); }
        else if (e.key.toLowerCase() === 'z') toggleZoom();
      });

      /* Touch swipe support in lightbox */
      let touchStartX = 0;
      lightbox.addEventListener('touchstart', (e) => {
        touchStartX = e.changedTouches[0].screenX;
      }, { passive: true });
      lightbox.addEventListener('touchend', (e) => {
        if (!state.lightboxOpen || state.lightboxZoomed) return;
        const delta = e.changedTouches[0].screenX - touchStartX;
        if (Math.abs(delta) > 55) {
          state.lightboxIndex += delta < 0 ? 1 : -1;
          updateLightboxContent();
        }
      }, { passive: true });

      /* ----------------------------------------------------------------------
         INQUIRY FORM & EMAIL COPY
         ---------------------------------------------------------------------- */
      const inquiryPills = document.querySelectorAll('#inquiryPills .pill-option');
      const projectTypeInput = document.getElementById('projectTypeInput');
      const inquiryForm = document.getElementById('inquiryForm');
      const formSuccess = document.getElementById('formSuccess');

      function selectInquiryPill(value) {
        projectTypeInput.value = value;
        inquiryPills.forEach(p => p.classList.toggle('selected', p.dataset.value === value));
      }

      inquiryPills.forEach(pill => {
        pill.addEventListener('click', () => selectInquiryPill(pill.dataset.value));
      });

      inquiryForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const name = document.getElementById('nameInput').value.trim();
        const email = document.getElementById('emailInput').value.trim();
        const message = document.getElementById('messageInput').value.trim();

        if (!name || !email || !email.includes('@') || !message) {
          showToast('Please complete your name, valid email, and brief.');
          return;
        }

        document.getElementById('successName').textContent = name.split(' ')[0];
        document.getElementById('successType').textContent = projectTypeInput.value;
        inquiryForm.style.display = 'none';
        formSuccess.classList.add('visible');
        showToast('Inquiry sent to Maren Solberg Studio');
      });

      document.getElementById('resetFormBtn').addEventListener('click', () => {
        inquiryForm.reset();
        selectInquiryPill('Editorial / Brand');
        formSuccess.classList.remove('visible');
        inquiryForm.style.display = 'block';
      });

      document.getElementById('copyEmailBtn').addEventListener('click', async () => {
        const email = 'studio@marensolberg.com';
        try {
          await navigator.clipboard.writeText(email);
          showToast('Email copied to clipboard');
        } catch {
          showToast(email);
        }
      });

      /* ----------------------------------------------------------------------
         SCROLL REVEAL & ACTIVE NAV HIGHLIGHT
         ---------------------------------------------------------------------- */
      const revealEls = document.querySelectorAll('.reveal');
      if ('IntersectionObserver' in window) {
        const revealObs = new IntersectionObserver((entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              entry.target.classList.add('is-visible');
              revealObs.unobserve(entry.target);
            }
          });
        }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });

        revealEls.forEach(el => revealObs.observe(el));

        // Active section nav highlight
        const sections = document.querySelectorAll('section[id]');
        const navLinks = document.querySelectorAll('.nav-link');
        const navObs = new IntersectionObserver((entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              const id = entry.target.getAttribute('id');
              navLinks.forEach(link => {
                link.classList.toggle('active', link.getAttribute('href') === `#${id}`);
              });
            }
          });
        }, { threshold: 0.35 });
        sections.forEach(sec => navObs.observe(sec));
      } else {
        revealEls.forEach(el => el.classList.add('is-visible'));
      }

      /* ----------------------------------------------------------------------
         INITIALIZE
         ---------------------------------------------------------------------- */
      initHero();
      renderFilters();
      renderGallery();
    })();
  </script>
</body>
</html>
